function normalizeBikeCatalog(catalog){const normalized={};Object.entries(catalog&&typeof catalog==='object'&&!Array.isArray(catalog)?catalog:{}).forEach(([brand,models])=>{if(Array.isArray(models)){const recovered={};models.forEach(value=>{if(typeof value==='string'&&value.trim())recovered[value.trim()]=[]});normalized[brand]=recovered}else if(models&&typeof models==='object'){normalized[brand]={...models}}else normalized[brand]={}});return normalized}
