function paginatedItems(items,key){const state=listStates[key],pages=Math.max(1,Math.ceil(items.length/10));state.page=Math.max(1,Math.min(state.page,pages));return items.slice((state.page-1)*10,state.page*10)}
function paginationMarkup(total,key){const page=listStates[key].page,pages=Math.max(1,Math.ceil(total/10)),start=Math.max(1,Math.min(page-2,pages-4)),end=Math.min(pages,start+4);return `<nav class="list-pagination" aria-label="Paginação"><span>${total?`${(page-1)*10+1}–${Math.min(page*10,total)}`:'0'} de ${total}</span><div><button type="button" class="btn ghost" data-page="${page-1}" ${page===1?'disabled':''}>Anterior</button>${start>1?'<button type="button" class="btn ghost" data-page="1">1</button><span>…</span>':''}${Array.from({length:end-start+1},(_,index)=>start+index).map(number=>`<button type="button" class="btn ${number===page?'primary':'ghost'}" data-page="${number}" ${number===page?'aria-current="page"':''}>${number}</button>`).join('')}${end<pages?`<span>…</span><button type="button" class="btn ghost" data-page="${pages}">${pages}</button>`:''}<button type="button" class="btn ghost" data-page="${page+1}" ${page===pages?'disabled':''}>Seguinte</button></div></nav>`}
function bindPagination(container,key,render){container.querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>{listStates[key].page=Number(button.dataset.page);render()})}

