function chequeDueDate(baseDate,term){const date=new Date(`${baseDate||isoDate(new Date())}T12:00:00`);date.setDate(date.getDate()+Number(term||0));return isoDate(date)}
function setupStockChequeFields(){document.querySelectorAll('[data-stock-status]').forEach(control=>{const item=stockBikes.find(x=>x.id===Number(control.dataset.stockStatus)),cell=control.closest('tr')?.querySelector('td');if(item?.chequeNumber&&cell&&!cell.querySelector('.stock-cheque')){const due=item.chequeDueDate||chequeDueDate(item.chequeCreatedAt,item.chequeTerm),line=document.createElement('div');line.className='cell-sub stock-cheque';line.textContent=`Cheque ${item.chequeNumber} · ${Number(item.chequeTerm||0)===0?'Pronto pagamento':`${item.chequeTerm} dias`} · ${new Date(`${due}T12:00:00`).toLocaleDateString('pt-PT')}${item.chequeCollectedEarly?' · cobrança antecipada':''}`;cell.append(line)}})}
function setupClientEditButton(){if(!location.hash.startsWith('#cliente/')||document.querySelector('#editClientData'))return;const actions=view.querySelector('.head-actions'),id=Number(location.hash.split('/')[1]);if(!actions||!clients.some(client=>client.id===id))return;const button=document.createElement('button');button.id='editClientData';button.className='btn ghost';button.textContent='Editar cliente';button.onclick=()=>openClientDataEditor(id);actions.prepend(button)}
function setupStockClientAssociations(){document.querySelectorAll('[data-stock-process]').forEach(select=>{const item=stockBikes.find(value=>value.id===Number(select.dataset.stockProcess)),client=clients.find(value=>value.id===item?.clientId);if(client&&!item.processId){const label=`Cliente: ${client.name}`;if(select.options[0].textContent!==label)select.options[0].textContent=label;select.options[0].selected=true}})}
function setupPastBookings(){document.querySelectorAll('[data-booking-id]').forEach(element=>{const booking=bookings.find(item=>item.id===Number(element.dataset.bookingId));if(booking&&!booking.completed&&bookingHasPassed(booking))element.classList.add('event-past')});document.querySelectorAll('[data-history-booking]').forEach(element=>{const booking=bookings.find(item=>item.id===Number(element.dataset.historyBooking)),badge=element.lastElementChild;if(booking&&!booking.invoice&&bookingHasPassed(booking)&&badge){if(badge.textContent!=='Realizada')badge.textContent='Realizada';if(badge.className!=='invoice-badge')badge.className='invoice-badge'}})}
new MutationObserver(()=>{setupStockVariantFields();setupListDeleteButtons();setupCalendarTimeRange();setupBossRoleEditor();setupStockChequeFields();setupClientEditButton();setupStockClientAssociations();setupPastBookings()}).observe(view,{childList:true,subtree:true});
