function openChequeArrivalModal(item,onSaved){document.querySelector('#chequeArrivalModal')?.remove();const receivedAt=isoDate(new Date()),modal=document.createElement('div');modal.id='chequeArrivalModal';modal.className='modal-backdrop';modal.innerHTML=`<section class="modal small-modal"><header><div><span class="eyebrow">MOTO RECEBIDA</span><h2>Registar receção e pagamento</h2></div><button class="icon-btn" type="button" data-close-cheque>×</button></header><form id="chequeArrivalForm"><div class="form-section"><p>Dados associados à receção da moto em ${new Date(`${receivedAt}T12:00:00`).toLocaleDateString('pt-PT')}.</p><div class="form-grid"><label class="full"><span>Método de pagamento</span><select name="paymentMethod" required><option value="Pronto pagamento">Pronto pagamento</option><option value="Cheque">Cheque</option></select></label><div class="full form-grid" data-arrival-cheque-fields hidden><label><span>Número do cheque</span><input name="chequeNumber" placeholder="Número do cheque"></label><label><span>Valor do cheque (€)</span><input name="chequeAmount" type="number" min="0" step="0.01" placeholder="0,00"></label><label><span>Prazo de cobrança</span><select name="chequeTerm"><option value="0">Pronto pagamento</option><option value="30">30 dias</option><option value="60">60 dias</option><option value="90" selected>90 dias</option></select></label></div><label><span>Fatura Nº (opcional)</span><input name="invoiceNumber" placeholder="Número da fatura"></label><label><span>VIN (opcional)</span><input name="vin" minlength="17" maxlength="17" value="${htmlEscape(item.vin||'')}" placeholder="17 caracteres"></label></div></div><footer><button type="button" class="btn ghost" data-close-cheque>Cancelar</button><button class="btn primary" type="submit">Confirmar receção</button></footer></form></section>`;document.body.append(modal);const form=modal.querySelector('form'),chequeFields=modal.querySelector('[data-arrival-cheque-fields]'),syncPayment=()=>{const cheque=form.elements.paymentMethod.value==='Cheque';chequeFields.hidden=!cheque;form.elements.chequeNumber.required=cheque;form.elements.chequeAmount.required=cheque};form.elements.paymentMethod.onchange=syncPayment;syncPayment();const close=()=>{modal.remove();onSaved?.(false)};modal.querySelectorAll('[data-close-cheque]').forEach(button=>button.onclick=close);modal.onclick=event=>{if(event.target===modal)close()};form.onsubmit=async event=>{event.preventDefault();const submit=form.querySelector('[type="submit"]'),values=new FormData(event.currentTarget),method=String(values.get('paymentMethod'));submit.disabled=true;item.status='Recebida';item.receiptRegisteredAt=new Date().toISOString();item.paymentMethod=method;item.invoiceNumber=String(values.get('invoiceNumber')||'').trim();item.vin=String(values.get('vin')||'').trim().toUpperCase();if(method==='Cheque'){item.chequeNumber=String(values.get('chequeNumber')).trim();item.chequeAmount=Number(String(values.get('chequeAmount')||'0').replace(',','.'))||0;item.chequeTerm=Number(values.get('chequeTerm'));item.chequeCreatedAt=receivedAt;item.chequeDueDate=chequeDueDate(receivedAt,item.chequeTerm);item.chequeCollectedEarly=false}else{delete item.chequeNumber;delete item.chequeAmount;delete item.chequeTerm;delete item.chequeCreatedAt;delete item.chequeDueDate;delete item.chequeCollectedEarly}saveStock();modal.remove();const process=processes.find(value=>String(value.id)===String(item.processId)||String(value.stockBikeId||'')===String(item.id)),matriculaPedida=process&&normalizedChecklist(process)[6];if(method==='Cheque'&&matriculaPedida){showToast('Moto recebida; a atualizar cheque e avisar a Contabilidade');await triggerChequeEarlyCollection(process,true)}else showToast(method==='Cheque'?'Moto recebida e cheque registado':'Moto recebida com pronto pagamento');onSaved?.(true)}}
function updateNavCounts(){const count=document.querySelector('#processNavCount');if(count)count.textContent=String(processes.filter(p=>!['Entregue','Cancelado'].includes(p.status)).length)}
function save(){let clientsChanged=false,stockChanged=false;processes.forEach(process=>{if(!process.uid)process.uid=`proc-${newEntityId()}`;if(process.stock==='Aguarda aprovação')process.stock='Por encomenda';if(process.status==='Entregue'){const purchaseDate=process.deliveredAt||isoDate(new Date());process.deliveredAt=purchaseDate;const client=clients.find(value=>value.id===process.clientId)||clients.find(value=>normalizePersonName(value.name)===normalizePersonName(process.client)),stock=stockBikes.find(value=>value.id===process.stockBikeId)||stockBikes.find(value=>value.processId===process.id);if(stock&&stock.status!=='Entregue'){stock.status='Entregue';stock.deliveredAt=purchaseDate;stockChanged=true}if(client){if(!Array.isArray(client.bikes))client.bikes=[];let bike=stock?client.bikes.find(value=>value.stockBikeId===stock.id):null;if(!bike)bike=client.bikes.find(value=>normalizePersonName(`${value.brand} ${value.model}`)===normalizePersonName(process.bike));if(!bike){const parts=String(process.bike||'').trim().split(/\s+/);bike={brand:parts.shift()||'',model:parts.join(' '),year:stock?.year||null};client.bikes.push(bike)}const before=bike.purchaseDate;Object.assign(bike,{purchaseDate,stockBikeId:stock?.id||bike.stockBikeId,brand:stock?.brand||bike.brand,model:stock?.model||bike.model,year:stock?.year||bike.year||null,color:stock?.color||bike.color||'',variant:stock?.variant||process.bikeVariant||bike.variant||null,vin:stock?.vin||bike.vin||null});if(before!==purchaseDate)clientsChanged=true}}});localStorage.setItem('emg-processes',JSON.stringify(processes));queueResourceSync('processes',processes);if(clientsChanged){localStorage.setItem('emg-clients',JSON.stringify(clients));queueResourceSync('clients',clients)}if(stockChanged){localStorage.setItem('emg-stock-bikes',JSON.stringify(stockBikes));queueResourceSync('stockBikes',stockBikes)}updateNavCounts()}
async function triggerChequeEarlyCollection(process){const bike=stockBikes.find(item=>item.processId===process?.id&&item.chequeNumber&&!item.chequeCollectedEarly);if(!bike||!remoteMode)return;try{await apiRequest('cheque-notifications.php',{method:'POST',body:JSON.stringify({processId:process.id,stockId:bike.id})});bike.chequeCollectedEarly=true;bike.chequeCollectionTriggeredAt=new Date().toISOString();saveStock();showToast(`Contabilidade avisada sobre o cheque ${bike.chequeNumber}`)}catch(error){showToast(`Falha ao avisar a contabilidade: ${error.message}`)}}
