function normalizedChecklist(process){
 if(!process.checkOwners||typeof process.checkOwners!=='object')process.checkOwners={};
 if(Array.isArray(process.checklist)&&process.checklist.length===12){
  process.checklist=[...process.checklist.slice(0,8),false,...process.checklist.slice(8)];
  process.checkOwners=Object.fromEntries(Object.entries(process.checkOwners).map(([key,value])=>[Number(key)>=8?String(Number(key)+1):key,value]));
 }else if(!Array.isArray(process.checklist)||process.checklist.length!==checklistLabels.length){
  const old=Array.from({length:12},(_,index)=>index<Number(process.checks||0));
  process.checklist=[...old.slice(0,8),false,...old.slice(8)];
 }
 process.checklist.forEach((checked,index)=>{if(checked&&!process.checkOwners[index])process.checkOwners[index]=process.owner||process.createdBy||'Registo anterior'});process.checks=process.checklist.filter(Boolean).length;return process.checklist
}
function checklistStatus(process,state=normalizedChecklist(process)){if(process.paymentType==='Financiamento'&&!state[4])return'Aguarda financiamento';if(state[12])return'Entregue';if(state[9])return'Pronta para entrega';if(state[11])return'Pagamento integral recebido';let latest=-1;state.slice(0,9).forEach((checked,index)=>{if(checked)latest=index});const statuses=['Novo processo','Proposta apresentada','Entrada paga',process.stock==='Por encomenda'?'Moto encomendada':'Moto reservada','Financiamento aprovado','Moto recebida','Matrícula pedida','Documentação paga','Documentação enviada'];return latest<0?'Novo processo':statuses[latest]}
const processTabContentChecklistBase=processTabContent;
processTabContent=function(process,tab){if(tab!=='checklist')return processTabContentChecklistBase(process,tab);const state=normalizedChecklist(process);return `<div class="checklist">${checklistLabels.map((label,index)=>`<div class="check-item"><button class="check ${state[index]?'checked':''}" data-check="${index}" ${state[index]?'disabled':''} title="${state[index]?'Validado por '+htmlEscape(process.checkOwners[index]||'Registo anterior'):'Clique para validar este passo'}"></button><div><b>${label}</b><small>${state[index]?'Validado e bloqueado':'Clique no pisco para validar'}</small></div>${state[index]?`<span class="cell-sub">✓ ${htmlEscape(process.checkOwners[index]||'Registo anterior')}</span>`:''}</div>`).join('')}</div><p class="payment-note">Cada passo fica bloqueado após a primeira validação e mantém o nome do utilizador.</p>`};
