function linkedProcessStockBike(process){return stockBikes.find(item=>item.id===process.stockBikeId||item.processId===process.id)}
function processBikeSituation(process){return linkedProcessStockBike(process)?.status||'Por encomendar'}
function paymentProgress(process){const total=processTotal(process),settled=(Number(process.paid)||0)+processTradeInValue(process);return total>0?Math.max(0,Math.min(100,settled/total*100)):0}
function tableRows(items){return items.map(p=>{const tradeIn=processTradeInValue(p);return `<tr data-id="${htmlEscape(p.id)}"><td><div class="client-cell"><span class="initials">${htmlEscape(initials(p.client))}</span><div><b>${htmlEscape(p.client)}</b><div class="cell-sub">${htmlEscape(p.id)}</div></div></div></td><td><b>${htmlEscape(p.bike)}${p.bikeVariant?` · ${htmlEscape(p.bikeVariant)}`:''}</b><div class="cell-sub">${htmlEscape(processBikeSituation(p))}</div></td><td><span class="pill ${htmlEscape(p.tone)}">${htmlEscape(p.status)}</span></td><td><b>${euros((Number(p.paid)||0)+tradeIn)} / ${euros(processTotal(p))}</b><div class="cell-sub">${tradeIn>0?'Pago + retoma':'Pago'}</div><div class="progress"><i style="width:${paymentProgress(p)}%"></i></div></td><td>${htmlEscape(p.owner||'Por atribuir')}</td><td>›</td></tr>`}).join('')}
function processTabContent(p,tab){
 if(tab==='payments')return `<div class="payment-summary"><div><span>Valor pago / entrada</span><b>${euros(p.paid||0)}</b></div><div><span>Valor da retoma</span><b>${euros(processTradeInValue(p))}</b></div><div><span>Acessórios</span><b>${euros(p.accessories||0)}</b></div><div class="payment-total"><span>Total acordado</span><b>${euros(processTotal(p))}</b></div><div class="payment-due"><span>A faltar</span><b>${euros(processOutstanding(p))}</b></div></div><div class="payment-note">O valor da retoma é abatido ao total acordado, juntamente com os pagamentos recebidos.</div>`;
 if(tab==='documents')return `<div class="documents-panel"><label class="upload-zone"><input id="documentUpload" type="file" accept=".jpg,.jpeg,.png,.pdf,image/jpeg,image/png,application/pdf" multiple><span class="upload-icon">⇧</span><b>Anexar documentos</b><small>JPG, PNG ou PDF · máximo 5 MB por ficheiro</small></label><div class="document-list" id="documentList"><p class="no-results">A carregar documentos...</p></div></div>`;
 return `<div class="checklist">${checklistLabels.map((x,i)=>`<div class="check-item"><button class="check ${i<p.checks?'checked':''}" data-check="${i}"></button><div><b>${x}</b><small>${i<p.checks?'Validado no processo':'Por validar'}</small></div>${i<p.checks?'<span class="cell-sub">✓ '+p.owner+'</span>':''}</div>`).join('')}</div>`;
}
function releaseProcessStock(process){const linked=stockBikes.filter(item=>item.processId===process.id||item.id===process.stockBikeId);linked.forEach(item=>{item.processId=null;item.clientId=null;if(['Em loja','Recebida'].includes(item.status))item.status='Em loja'});delete process.stockBikeId;if(linked.length)saveStock();return linked.length}
function addProcessBikeToClient(process,item){const client=clients.find(value=>value.id===process.clientId)||clients.find(value=>value.name===process.client);addStockBikeToClient(client,item)}
function openFinanceApprovalMotoModal(process){document.querySelector('#financeApprovalMotoModal')?.remove();const available=availableStockBikes(),modal=document.createElement('div');modal.id='financeApprovalMotoModal';modal.className='modal-backdrop';modal.innerHTML=`<section class="modal"><header><div><span class="eyebrow">FINANCIAMENTO APROVADO</span><h2>Associar moto ao processo</h2></div><button class="icon-btn" data-close-finance-bike>×</button></header><form id="financeApprovalMotoForm"><div class="form-section"><div class="segmented"><button type="button" class="active" data-bike-source="stock">Moto em stock</button><button type="button" data-bike-source="order">Por encomenda</button></div><input type="hidden" name="source" value="stock"><div id="financeStockChoice" class="form-grid"><label class="full"><span>Moto disponível em loja</span><select name="stockBikeId"><option value="">Selecionar moto</option>${available.map(item=>`<option value="${item.id}">${htmlEscape(item.reference)} · ${htmlEscape(item.brand)} ${htmlEscape(item.model)} · ${htmlEscape(item.color||'Cor por definir')}</option>`).join('')}</select></label></div><div id="financeOrderChoice" class="form-grid" hidden><label><span>Referência da encomenda</span><input name="reference" placeholder="Ex.: STK-26004"></label><label><span>Marca</span><select name="brand"><option value="">Selecionar marca</option>${Object.keys(newBikeCatalog).map(brand=>`<option>${htmlEscape(brand)}</option>`).join('')}</select></label><label><span>Modelo</span><select name="model"><option value="">Selecione primeiro a marca</option></select></label><label><span>Cor</span><input name="color" placeholder="Introduzir cor"></label></div></div><footer><button type="button" class="btn ghost" data-close-finance-bike>Cancelar</button><button class="btn primary" type="submit">Associar moto</button></footer></form></section>`;document.body.append(modal);const form=modal.querySelector('form'),close=()=>modal.remove(),sync=source=>{form.elements.source.value=source;modal.querySelector('#financeStockChoice').hidden=source!=='stock';modal.querySelector('#financeOrderChoice').hidden=source!=='order';modal.querySelectorAll('[data-bike-source]').forEach(button=>button.classList.toggle('active',button.dataset.bikeSource===source))};modal.querySelectorAll('[data-close-finance-bike]').forEach(button=>button.onclick=close);modal.querySelectorAll('[data-bike-source]').forEach(button=>button.onclick=()=>sync(button.dataset.bikeSource));form.elements.brand.onchange=()=>{form.elements.model.innerHTML='<option value="">Selecionar modelo</option>'+Object.keys(newBikeCatalog[form.elements.brand.value]||{}).map(model=>`<option>${htmlEscape(model)}</option>`).join('')};form.onsubmit=event=>{event.preventDefault();const values=new FormData(form),source=values.get('source');let item;if(source==='stock'){item=stockBikes.find(value=>value.id===Number(values.get('stockBikeId')));if(!item){showToast('Selecione uma moto disponível');return}}else{const reference=String(values.get('reference')).trim(),brand=String(values.get('brand')),model=String(values.get('model')),color=String(values.get('color')).trim();if(!reference||!brand||!model||!color){showToast('Preencha os dados da encomenda');return}if(stockBikes.some(value=>value.reference.toLowerCase()===reference.toLowerCase())){showToast('Já existe uma moto com esta referência');return}item={id:Date.now(),reference,brand,model,color,condition:'Nova',status:'Encomendada',processId:null};stockBikes.unshift(item)}associateStockBike(item,process.id);process.stock=source==='stock'?'Em stock':'Por encomenda';process.bike=`${item.brand} ${item.model}`;process.color=item.color;addProcessBikeToClient(process,item);saveStock();save();close();showToast(source==='stock'?'Moto em stock associada ao cliente':'Encomenda criada e associada ao cliente');detail(process.id)}}
function openProcessEditor(process){document.querySelector('#processEditModal')?.remove();const linked=stockBikes.some(item=>item.processId===process.id||item.id===process.stockBikeId),modal=document.createElement('div');modal.id='processEditModal';modal.className='modal-backdrop';modal.innerHTML=`<section class="modal process-edit-modal"><header><div><span class="eyebrow">EDITAR PROCESSO</span><h2>${htmlEscape(process.id)}</h2></div><button class="icon-btn" data-close-process-edit>×</button></header><form id="processEditForm"><div class="form-section"><div class="form-grid"><label><span>Cliente</span><input name="client" required value="${htmlEscape(process.client)}"></label><label><span>Responsável pela alteração</span><input readonly value="${htmlEscape(sessionEmployeeName())}"></label><label><span>Moto</span><input name="bike" required value="${htmlEscape(process.bike)}" ${linked?'readonly':''}></label><label><span>Configuração</span><input name="bikeVariant" value="${htmlEscape(process.bikeVariant||'')}"></label><label><span>Cor</span><input name="color" value="${htmlEscape(process.color||'')}"></label><label><span>Disponibilidade</span><select name="stock"><option ${process.stock==='Em stock'?'selected':''}>Em stock</option><option ${process.stock==='Por encomenda'?'selected':''}>Por encomenda</option></select></label><label><span>Preço acordado (€)</span><input name="price" type="number" min="0" step="0.01" required value="${Number(process.price)||0}"></label><label><span>Entrada / valor pago (€)</span><input name="paid" type="number" min="0" step="0.01" value="${Number(process.paid)||0}"></label><label><span>Acessórios (€)</span><input name="accessories" type="number" min="0" step="0.01" value="${Number(process.accessories)||0}"></label><label><span>Pagamento</span><select name="paymentType"><option ${process.paymentType==='Pronto pagamento'?'selected':''}>Pronto pagamento</option><option ${process.paymentType==='Financiamento'?'selected':''}>Financiamento</option></select></label><label class="full"><span>Estado</span><select name="status">${processStatuses.map(status=>`<option ${status===process.status?'selected':''}>${status}</option>`).join('')}</select></label><label class="full"><span>Nota</span><textarea name="note">${htmlEscape(process.note||'')}</textarea></label></div>${linked?'<p class="cell-sub">A moto está associada ao stock. A marca e o modelo devem ser alterados no registo da moto.</p>':''}</div><footer><button type="button" class="btn ghost" data-close-process-edit>Cancelar</button><button class="btn primary" type="submit">Guardar alterações</button></footer></form></section>`;document.body.append(modal);const close=()=>modal.remove();modal.querySelectorAll('[data-close-process-edit]').forEach(button=>button.onclick=close);modal.onclick=e=>{if(e.target===modal)close()};modal.querySelector('form').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target),newStatus=String(form.get('status'));process.client=String(form.get('client')).trim();process.bike=String(form.get('bike')).trim();process.bikeVariant=String(form.get('bikeVariant')).trim()||null;process.color=String(form.get('color')).trim()||'Cor por definir';process.stock=String(form.get('stock'));process.price=Number(form.get('price'));process.paid=Number(form.get('paid'));process.accessories=Number(form.get('accessories'));process.paymentType=String(form.get('paymentType'));process.status=newStatus;process.tone=statusTone(newStatus);process.note=String(form.get('note')).trim();if(newStatus==='Cancelado')releaseProcessStock(process);assignProcessOwner(process);save();close();showToast(newStatus==='Cancelado'?'Processo cancelado e moto libertada':'Processo atualizado');detail(process.id)}}
const openProcessEditorBaseForApproval=openProcessEditor;
openProcessEditor=function(process){openProcessEditorBaseForApproval(process);const form=document.querySelector('#processEditForm');if(!form)return;const hasLinkedBike=stockBikes.some(item=>item.processId===process.id||item.id===process.stockBikeId);if(process.paymentType==='Financiamento'&&!hasLinkedBike){const availability=form.elements.stock;availability.innerHTML='<option>Por encomenda</option>';availability.value='Por encomenda'}form.addEventListener('submit',event=>{const newStatus=String(new FormData(event.currentTarget).get('status')),needsBike=process.paymentType==='Financiamento'&&newStatus==='Financiamento aprovado'&&!stockBikes.some(item=>item.processId===process.id||item.id===process.stockBikeId);if(needsBike)queueMicrotask(()=>openFinanceApprovalMotoModal(process))},true)};
view.addEventListener('change',event=>{if(event.target.id!=='processStatus'||event.target.value!=='Financiamento aprovado')return;const process=processes.find(item=>item.id===location.hash.split('/')[1]);if(process?.paymentType==='Financiamento'&&!stockBikes.some(item=>item.processId===process.id||item.id===process.stockBikeId))queueMicrotask(()=>openFinanceApprovalMotoModal(process))},true);
function deleteProcess(process){if(!confirm(`Apagar definitivamente o processo ${process.id} de ${process.client}?`))return;const released=releaseProcessStock(process);processes=processes.filter(item=>item.uid?item.uid!==process.uid:!(item.id===process.id&&item.clientId===process.clientId));deleteRemoteEntity('processes',process.id,process.uid||'');localStorage.setItem('emg-processes',JSON.stringify(processes));updateNavCounts();showToast(released?'Processo apagado e moto devolvida ao stock':'Processo apagado');location.hash='processos'}
function detail(id,activeTab='checklist'){const p=processes.find(x=>x.id===id);if(!p){showToast('Processo não encontrado ou já eliminado');location.hash='processos';return}const totalSteps=checklistLabels.length;view.innerHTML=`${pageHead('PROCESSO DE COMPRA',`<span class="detail-head"><button class="back-btn" data-go="processos">←</button><span>${htmlEscape(p.id)}</span></span>`,`${htmlEscape(p.client)} · responsável: ${htmlEscape(p.owner||'por atribuir')}`,'<div class="process-danger-actions"><button class="btn ghost" id="editProcess">Editar</button><button class="btn danger" id="deleteProcess">Apagar</button></div><select class="btn primary status-select" id="processStatus" aria-label="Estado do processo">'+processStatuses.map(s=>`<option ${s===p.status?'selected':''}>${htmlEscape(s)}</option>`).join('')+'</select>')}
 <div class="detail-grid"><div><article class="card summary-banner"><div class="bike-title"><span class="bike-icon">◈</span><div><h3>${p.bike}${p.bikeVariant?` · ${htmlEscape(p.bikeVariant)}`:''}</h3><div class="cell-sub">${p.color} · ${htmlEscape(processBikeSituation(p))}</div></div></div><div class="metric"><small>VALOR ACORDADO</small><b>${euros(processTotal(p))}</b></div><div class="metric"><small>PAGO + RETOMA</small><b>${euros((Number(p.paid)||0)+processTradeInValue(p))}</b></div><div class="metric"><small>POR PAGAR</small><b>${euros(processOutstanding(p))}</b></div></article>
 <article class="card" style="margin-top:20px"><div class="tabs"><button data-tab="checklist" class="${activeTab==='checklist'?'active':''}">Checklist</button><button data-tab="payments" class="${activeTab==='payments'?'active':''}">Pagamentos</button><button data-tab="documents" class="${activeTab==='documents'?'active':''}">Documentos</button></div><div class="tab-content">${processTabContent(p,activeTab)}</div></article></div>
 <aside><article class="card"><div class="side-section"><h3>Estado do processo</h3><span class="pill ${p.tone}">${p.status}</span><div class="progress" style="width:100%;margin-top:14px"><i style="width:${Math.min(p.checks,totalSteps)/totalSteps*100}%"></i></div><div class="cell-sub" style="margin-top:7px">${Math.min(p.checks,totalSteps)} de ${totalSteps} passos concluídos</div></div><div class="side-section"><h3>Detalhes</h3><div class="info-row"><span>Cliente</span><b>${p.client}</b></div><div class="info-row"><span>Contacto</span><b>${clients.find(c=>c.name===p.client)?.phone||'Por preencher'}</b></div>${p.bikeVariant?`<div class="info-row"><span>Configuração</span><b>${p.bikeVariant}</b></div>`:''}<div class="info-row"><span>Pagamento</span><b>${p.paymentType||'Por definir'}</b></div>${p.paymentType==='Financiamento'?`<div class="info-row"><span>Modalidade</span><b>${p.financingType||'Por definir'}</b></div>`:''}<div class="info-row"><span>Responsável</span><b>${p.owner||'Por atribuir'}</b></div></div>${p.paymentType==='Financiamento'?`<div class="side-section"><h3>Documentos do financiamento</h3><div class="finance-doc-list">${financeDocumentLabels.map(doc=>`<label><input type="checkbox" data-finance-doc="${doc}" ${(p.financeDocs||[]).includes(doc)?'checked':''}> <span>${doc}</span></label>`).join('')}</div></div>`:''}<div class="side-section"><h3>Nota do processo</h3><div class="note">${p.note||'Sem notas adicionadas.'}</div></div></article></aside></div>`;
 bindCommon();document.querySelector('#editProcess').onclick=()=>openProcessEditor(p);document.querySelector('#deleteProcess').onclick=()=>deleteProcess(p);document.querySelectorAll('[data-tab]').forEach(btn=>btn.onclick=()=>detail(p.id,btn.dataset.tab));document.querySelectorAll('[data-check]').forEach(btn=>btn.onclick=()=>{btn.classList.toggle('checked');p.checks=document.querySelectorAll('.check.checked').length;assignProcessOwner(p);save();showToast('Checklist atualizada')});document.querySelectorAll('[data-finance-doc]').forEach(box=>box.onchange=()=>{p.financeDocs=[...document.querySelectorAll('[data-finance-doc]:checked')].map(x=>x.dataset.financeDoc);assignProcessOwner(p);save();showToast('Documentos atualizados')});document.querySelector('#processStatus').onchange=e=>{p.status=e.target.value;if(p.status==='Entregue'&&!p.deliveredAt)p.deliveredAt=isoDate(new Date());if(p.status!=='Entregue')delete p.deliveredAt;if(p.status==='Cancelado')releaseProcessStock(p);p.tone=statusTone(p.status);assignProcessOwner(p);save();showToast(p.status==='Cancelado'?'Processo cancelado e moto libertada':`Estado atualizado: ${p.status}`);detail(p.id,activeTab)};if(activeTab==='documents'){document.querySelector('#documentUpload').onchange=e=>uploadDocuments(p.id,[...e.target.files]);renderDocuments(p.id)};
}
function openDocumentDb(){return new Promise((resolve,reject)=>{const request=indexedDB.open('emg-documents',1);request.onupgradeneeded=()=>request.result.createObjectStore('files',{keyPath:'key'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function uploadDocuments(processId,files){const allowed=['image/jpeg','image/png','application/pdf'],valid=files.filter(f=>allowed.includes(f.type)&&f.size<=5*1024*1024);if(valid.length!==files.length)showToast('Alguns ficheiros foram ignorados: formato ou tamanho inválido');if(remoteMode){const form=new FormData();form.append('process',processId);valid.forEach(file=>form.append('files[]',file));try{const response=await fetch(`api/documents.php?process=${encodeURIComponent(processId)}`,{method:'POST',credentials:'same-origin',headers:{'X-CSRF-Token':csrfToken},body:form}),data=await response.json();if(!response.ok)throw new Error(data.error||'Falha no upload');showToast(`${data.created} documento(s) anexado(s)`);renderDocuments(processId)}catch(error){showToast(error.message)}return}const db=await openDocumentDb(),tx=db.transaction('files','readwrite'),store=tx.objectStore('files');valid.forEach(file=>store.put({key:`${processId}-${Date.now()}-${file.name}`,processId,name:file.name,type:file.type,size:file.size,created:new Date().toISOString(),blob:file}));tx.oncomplete=()=>{db.close();showToast(`${valid.length} documento(s) anexado(s)`);renderDocuments(processId)}}
async function getDocuments(processId){if(remoteMode){const response=await apiRequest(`documents.php?process=${encodeURIComponent(processId)}`);return response.documents||[]}const db=await openDocumentDb();return new Promise((resolve,reject)=>{const req=db.transaction('files').objectStore('files').getAll();req.onsuccess=()=>{db.close();resolve(req.result.filter(x=>x.processId===processId))};req.onerror=()=>reject(req.error)})}
async function renderDocuments(processId){const list=document.querySelector('#documentList');if(!list)return;try{const docs=await getDocuments(processId);list.innerHTML=docs.length?docs.map((d,i)=>`<div class="document-item"><span class="document-type">${d.type==='application/pdf'?'PDF':'IMG'}</span><div><b>${d.name}</b><small>${(d.size/1024).toFixed(0)} KB · ${new Date(d.created).toLocaleDateString('pt-PT')}</small></div><button class="btn ghost" data-download-doc="${i}">Descarregar</button></div>`).join(''):'<p class="no-results">Ainda não existem documentos anexados.</p>';document.querySelectorAll('[data-download-doc]').forEach(btn=>btn.onclick=()=>{const d=docs[Number(btn.dataset.downloadDoc)];if(remoteMode){location.href=`api/documents.php?process=${encodeURIComponent(processId)}&download=${encodeURIComponent(d.id)}`;return}const url=URL.createObjectURL(d.blob),a=document.createElement('a');a.href=url;a.download=d.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}catch(error){list.innerHTML=`<p class="no-results">${error.message}</p>`}}
function absenceMonthCalendar(reference){const year=reference.getFullYear(),month=reference.getMonth(),first=new Date(year,month,1),gridStart=mondayOf(first),today=isoDate(new Date()),days=Array.from({length:42},(_,i)=>{const d=new Date(gridStart);d.setDate(d.getDate()+i);return d});return `<article class="card absence-calendar"><div class="calendar-toolbar"><div><button class="icon-btn" data-absence-month="-1">‹</button><button class="btn ghost" id="absenceToday">Hoje</button><button class="icon-btn" data-absence-month="1">›</button></div><h3>${new Intl.DateTimeFormat('pt-PT',{month:'long',year:'numeric'}).format(reference)}</h3><span class="absence-legend"><i class="vacation"></i> Férias <i class="missing"></i> Falta</span></div><div class="absence-weekdays">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(x=>`<span>${x}</span>`).join('')}</div><div class="absence-month-grid">${days.map(d=>{const date=isoDate(d),events=absences.filter(a=>date>=a.startDate&&date<=a.endDate);return `<div class="absence-day ${d.getMonth()!==month?'outside':''} ${date===today?'today':''}"><b>${d.getDate()}</b><div>${events.map(a=>`<button class="absence-event ${a.type==='Férias'?'vacation':'missing'}" data-absence-id="${a.id}" title="${a.employee} · ${a.startTime}–${a.endTime}"><span>${a.type==='Férias'?'☼':'!'}</span> ${a.employee.split(' ')[0]}</button>`).join('')}</div></div>`}).join('')}</div></article>`}
function teamPage(){const today=isoDate(new Date()),awayToday=absences.filter(a=>today>=a.startDate&&today<=a.endDate),mine=absences.filter(a=>a.employee===currentUser?.name).sort((a,b)=>`${b.startDate}${b.startTime}`.localeCompare(`${a.startDate}${a.startTime}`));view.innerHTML=pageHead('RECURSOS HUMANOS','Equipa, férias & faltas','Calendário partilhado para registar períodos de férias e faltas da equipa.','<button class="btn primary" id="newAbsence">＋ Marcar ausência</button>')+`<section class="stats-grid"><article class="stat-card"><div class="stat-top"><span>Total da equipa</span><span class="stat-icon">♧</span></div><div class="stat-value">${employees.length}</div><span class="trend neutral">Colaboradores ativos</span></article><article class="stat-card"><div class="stat-top"><span>Ao serviço hoje</span><span class="stat-icon">✓</span></div><div class="stat-value">${employees.length-new Set(awayToday.map(a=>a.employee)).size}</div><span class="trend">Equipa disponível</span></article><article class="stat-card"><div class="stat-top"><span>De férias hoje</span><span class="stat-icon">☼</span></div><div class="stat-value">${awayToday.filter(a=>a.type==='Férias').length}</div><span class="trend neutral">Ausências registadas</span></article><article class="stat-card"><div class="stat-top"><span>Faltas hoje</span><span class="stat-icon">!</span></div><div class="stat-value">${awayToday.filter(a=>a.type==='Falta').length}</div><span class="trend neutral">Ausências parciais ou totais</span></article></section><div class="absence-layout">${absenceMonthCalendar(absenceCalendarDate)}<aside class="card absence-side"><div class="card-head"><h3>As minhas marcações</h3><span class="cell-sub">${mine.length}</span></div><div class="absence-list">${mine.length?mine.map(a=>`<div class="absence-list-item"><span class="absence-type ${a.type==='Férias'?'vacation':'missing'}">${a.type}</span><div><b>${a.startDate===a.endDate?new Date(`${a.startDate}T12:00:00`).toLocaleDateString('pt-PT'):`${new Date(`${a.startDate}T12:00:00`).toLocaleDateString('pt-PT')} – ${new Date(`${a.endDate}T12:00:00`).toLocaleDateString('pt-PT')}`}</b><small>${a.startTime} – ${a.endTime}</small></div><button class="icon-btn" data-delete-absence="${a.id}" title="Apagar">×</button></div>`).join(''):'<div class="no-results">Ainda não marcou férias ou faltas.</div>'}</div></aside></div><div class="modal-backdrop" id="absenceModal" hidden><section class="modal small-modal"><header><div><span class="eyebrow">NOVA AUSÊNCIA</span><h2>Marcar férias ou falta</h2></div><button class="icon-btn" id="closeAbsence">×</button></header><form id="absenceForm"><div class="form-section"><div class="selected-client"><span class="initials">${initials(currentUser?.name||'U')}</span><div><b>${currentUser?.name||'Utilizador'}</b><small>A marcação ficará associada ao utilizador autenticado</small></div></div><div class="form-grid"><label><span>Tipo</span><select name="type" id="absenceType"><option>Férias</option><option>Falta</option></select></label><span></span><label><span>Dia de início</span><input name="startDate" type="date" required></label><label id="absenceEndDateField"><span>Dia de fim</span><input name="endDate" type="date" required></label><label><span>Das</span><input name="startTime" type="time" required value="09:00"></label><label><span>Até às</span><input name="endTime" type="time" required value="18:00"></label><label class="full"><span>Observações</span><textarea name="notes" placeholder="Informação opcional..."></textarea></label></div></div><footer><button type="button" class="btn ghost" id="cancelAbsence">Cancelar</button><button class="btn primary" type="submit">Guardar marcação</button></footer></form></section></div>`;bindCommon();const modal=document.querySelector('#absenceModal'),close=()=>modal.hidden=true;document.querySelector('#newAbsence').onclick=()=>modal.hidden=false;document.querySelector('#closeAbsence').onclick=close;document.querySelector('#cancelAbsence').onclick=close;modal.onclick=e=>{if(e.target===modal)close()};document.querySelector('#absenceType').onchange=e=>{const missing=e.target.value==='Falta',field=document.querySelector('#absenceEndDateField'),start=document.querySelector('#absenceForm [name="startDate"]'),end=document.querySelector('#absenceForm [name="endDate"]');field.hidden=missing;end.required=!missing;if(missing)end.value=start.value};document.querySelector('#absenceForm [name="startDate"]').onchange=e=>{if(document.querySelector('#absenceType').value==='Falta')document.querySelector('#absenceForm [name="endDate"]').value=e.target.value};document.querySelector('#absenceForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),type=f.get('type'),startDate=f.get('startDate'),endDate=type==='Falta'?startDate:f.get('endDate'),startTime=f.get('startTime'),endTime=f.get('endTime');if(`${endDate}T${endTime}`<=`${startDate}T${startTime}`){showToast('A data/hora final deve ser posterior ao início');return}absences.push({id:Date.now(),employee:currentUser.name,type,startDate,endDate,startTime,endTime,notes:String(f.get('notes')).trim()});saveAbsences();close();showToast(`${type} registada com sucesso`);teamPage()};document.querySelectorAll('[data-absence-month]').forEach(b=>b.onclick=()=>{absenceCalendarDate=new Date(absenceCalendarDate.getFullYear(),absenceCalendarDate.getMonth()+Number(b.dataset.absenceMonth),1);teamPage()});document.querySelector('#absenceToday').onclick=()=>{absenceCalendarDate=new Date();teamPage()};document.querySelectorAll('[data-delete-absence]').forEach(b=>b.onclick=()=>{if(!confirm('Apagar esta marcação?'))return;absences=absences.filter(a=>a.id!==Number(b.dataset.deleteAbsence));saveAbsences();showToast('Marcação apagada');teamPage()});document.querySelectorAll('[data-absence-id]').forEach(b=>b.onclick=()=>{const a=absences.find(x=>x.id===Number(b.dataset.absenceId));showToast(`${a.employee} · ${a.type} · ${a.startTime}–${a.endTime}`)})}
