absenceMonthCalendar=function(reference){const year=reference.getFullYear(),month=reference.getMonth(),first=new Date(year,month,1),gridStart=mondayOf(first),today=isoDate(new Date()),days=Array.from({length:42},(_,i)=>{const d=new Date(gridStart);d.setDate(d.getDate()+i);return d}),eventClass=a=>a.type==='Férias'?'vacation':a.type==='Nota'?'note':'missing',eventIcon=a=>a.type==='Férias'?'☼':a.type==='Nota'?'✎':'!';return `<article class="card absence-calendar"><div class="calendar-toolbar"><div><button class="icon-btn" data-absence-month="-1">‹</button><button class="btn ghost" id="absenceToday">Hoje</button><button class="icon-btn" data-absence-month="1">›</button></div><h3>${new Intl.DateTimeFormat('pt-PT',{month:'long',year:'numeric'}).format(reference)}</h3><span class="absence-legend"><i class="vacation"></i> Férias <i class="missing"></i> Falta <i class="note"></i> Nota</span></div><div class="absence-weekdays">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(x=>`<span>${x}</span>`).join('')}</div><div class="absence-month-grid">${days.map(d=>{const date=isoDate(d),events=absences.filter(a=>date>=a.startDate&&date<=a.endDate);return `<div class="absence-day ${d.getMonth()!==month?'outside':''} ${date===today?'today':''}"><b>${d.getDate()}</b><div>${events.map(a=>`<button class="absence-event ${eventClass(a)}" data-absence-id="${a.id}" title="${htmlEscape(a.employee)} · ${htmlEscape(a.type)}${a.startTime||a.endTime?` · ${htmlEscape(a.startTime||'--:--')}–${htmlEscape(a.endTime||'--:--')}`:''}${a.notes?` · ${htmlEscape(a.notes)}`:''}"><span>${eventIcon(a)}</span> ${htmlEscape(a.employee.split(' ')[0])}</button>`).join('')}</div></div>`}).join('')}</div></article>`};
