function exportChequesPdf(cheques=accountingCheques()){const generated=new Date().toLocaleString('pt-PT'),popup=window.open('','_blank');if(!popup){showToast('O navegador bloqueou a janela de exportação');return}popup.document.write(`<!doctype html><html lang="pt"><head><meta charset="utf-8"><title>Mapa de Cheques - Motogreen</title><style>body{font-family:Arial,sans-serif;color:#173027;padding:30px}header{border-bottom:3px solid #15935f;margin-bottom:22px;padding-bottom:14px}h1{margin:0 0 6px;font-size:24px}p{margin:0;color:#66756e}table{width:100%;border-collapse:collapse;font-size:12px}th{background:#e8f5ef;text-align:left;color:#0b5d46}th,td{padding:10px;border:1px solid #d8e5df}td:nth-child(2){font-weight:bold}.empty{text-align:center;padding:30px;color:#66756e}@media print{body{padding:5px}thead{display:table-header-group}}</style></head><body><header><h1>Motogreen · Mapa de Cheques</h1><p>Exportado em ${htmlEscape(generated)}</p></header><table><thead><tr><th>Encomenda / Fatura</th><th>Número do cheque</th><th>Data de vencimento</th></tr></thead><tbody>${cheques.length?cheques.map(item=>`<tr><td>${htmlEscape(item.documentNumber)}</td><td>${htmlEscape(item.chequeNumber)}</td><td>${item.dueDate?new Date(`${item.dueDate}T12:00:00`).toLocaleDateString('pt-PT'):'Data por definir'}</td></tr>`).join(''):'<tr><td class="empty" colspan="3">Sem cheques registados.</td></tr>'}</tbody></table><script>window.onload=()=>window.print()<\/script></body></html>`);popup.document.close()}
