function syncClientBikeBookings(client,bike,previous){const oldFull=normalizePersonName(`${previous.brand||''} ${previous.model||''}`),oldModel=normalizePersonName(previous.model||''),singleBike=(client.bikes||[]).length===1;let changed=false;bookings.filter(booking=>bookingBelongsToClient(booking,client)).forEach(booking=>{const currentVehicle=normalizePersonName(String(booking.bike||'').split('·')[0]);if(singleBike||currentVehicle===oldFull||currentVehicle===oldModel){booking.bike=clientBikeLabel(bike);changed=true}});if(changed)saveBookings();return changed}
