const openProcessEditorChecklistBase=openProcessEditor;
openProcessEditor=function(process){normalizedChecklist(process);openProcessEditorChecklistBase(process);const form=document.querySelector('#processEditForm');if(!form)return;const section=document.createElement('div');section.className='form-section process-edit-checklist';section.innerHTML=`<h3>Checklist do processo</h3><p>No modo de edição pode corrigir qualquer passo. O nome da primeira pessoa que o validou é mantido.</p><div class="document-checks">${checklistLabels.map((label,index)=>`<label><input type="checkbox" name="processChecklist" value="${index}" ${process.checklist[index]?'checked':''}> <span>${htmlEscape(label)}</span>${process.checkOwners[index]?` <small>· ${htmlEscape(process.checkOwners[index])}</small>`:''}</label>`).join('')}</div></div>`;form.querySelector('footer').before(section);const boxes=[...section.querySelectorAll('[name="processChecklist"]')],syncStatus=()=>{const state=checklistLabels.map((_,index)=>boxes.some(box=>Number(box.value)===index&&box.checked));form.elements.status.value=checklistStatus(process,state)};boxes.forEach(box=>box.onchange=syncStatus);form.addEventListener('submit',()=>{const previous=[...process.checklist],state=checklistLabels.map((_,index)=>boxes.some(box=>Number(box.value)===index&&box.checked));state.forEach((checked,index)=>{if(checked&&!previous[index]&&!process.checkOwners[index])process.checkOwners[index]=sessionEmployeeName()});process.checklist=state;process.checks=state.filter(Boolean).length;form.elements.status.value=checklistStatus(process,state)},true)};
