let processListMode='active';
function isArchivedProcess(process){return ['Entregue','Cancelado'].includes(process.status)}
processList=function(){
 const activeCount=processes.filter(process=>!isArchivedProcess(process)).length,archivedCount=processes.filter(isArchivedProcess).length;
 view.innerHTML=pageHead('COMERCIAL','Processos de compra','Consulte separadamente os processos ativos e os processos finalizados.','<button class="btn primary new-process">＋ Novo processo</button>')+`
 <div class="process-view-switch" role="tablist"><button class="${processListMode==='active'?'active':''}" data-process-view="active">Ativos <span>${activeCount}</span></button><button class="${processListMode==='archived'?'active':''}" data-process-view="archived">Finalizados <span>${archivedCount}</span></button></div>
 <div class="table-tools"><input class="filter-search" id="processSearch" placeholder="Pesquisar processo, cliente ou moto..."></div>
 <article class="card"><table class="process-table"><thead><tr><th>CLIENTE / PROCESSO</th><th>MOTO</th><th>ESTADO</th><th>VALORES</th><th>RESPONSÁVEL</th><th></th></tr></thead><tbody id="processBody"></tbody></table><div id="processPagination"></div></article>`;
 bindCommon();const search=document.querySelector('#processSearch');search.value=listStates.processes.query;
 const render=()=>{const query=listStates.processes.query.toLowerCase(),archived=processListMode==='archived',items=processes.filter(process=>isArchivedProcess(process)===archived&&(process.client+process.bike+process.id).toLowerCase().includes(query));document.querySelector('#processBody').innerHTML=tableRows(paginatedItems(items,'processes'))||`<tr><td colspan="6" class="no-results">Não existem processos ${archived?'finalizados':'ativos'}.</td></tr>`;const pagination=document.querySelector('#processPagination');pagination.innerHTML=paginationMarkup(items.length,'processes');bindPagination(pagination,'processes',render);bindRows()};
 document.querySelectorAll('[data-process-view]').forEach(button=>button.onclick=()=>{processListMode=button.dataset.processView;listStates.processes.page=1;processList()});search.oninput=event=>{listStates.processes.query=event.target.value;listStates.processes.page=1;render()};render()
};

function tomorrowIso(){const date=new Date();do{date.setDate(date.getDate()+1)}while(date.getDay()===0||date.getDay()===6);return isoDate(date)}
triggerChequeEarlyCollection=async function(process,force=false){
 let bike=stockBikes.find(item=>item.processId===process?.id)||stockBikes.find(item=>item.id===process?.stockBikeId);if(!bike){showToast('Não existe uma moto de stock associada a este processo');return false}if(!bike.chequeNumber){showToast('A moto associada não tem número de cheque registado');return false}
 const dueDate=tomorrowIso(),stateUpdatedAt=new Date().toISOString();bike.processId=process.id;process.stockBikeId=bike.id;bike.chequeDueDate=dueDate;bike.chequeCollectionTriggeredAt=stateUpdatedAt;bike.chequeStateUpdatedAt=stateUpdatedAt;bike.chequeNotificationPending=true;clearTimeout(syncTimers.stockBikes);localStorage.setItem('emg-stock-bikes',JSON.stringify(stockBikes));save();
 if(!remoteMode){showToast(`Cheque ${bike.chequeNumber}: cobrança prevista para ${new Date(`${dueDate}T12:00:00`).toLocaleDateString('pt-PT')}`);return true}
 try{const delta=changedRecords('stockBikes',stockBikes);if(delta.length){const synced=await apiRequest('state-write.php',{method:'POST',body:encodedStateBody({resource:'stockBikes',data:delta,partial:true})});if(Array.isArray(synced.data))applyServerResource('stockBikes',synced.data)}bike=stockBikes.find(item=>String(item.id)===String(bike.id))||bike;const response=await apiRequest('cheque-notifications.php',{method:'POST',body:JSON.stringify({processId:process.id,stockId:bike.id,force})});bike.chequeDueDate=response?.dueDate||dueDate;bike.chequeStateUpdatedAt=response?.chequeStateUpdatedAt||stateUpdatedAt;bike.chequeCollectedEarly=false;bike.chequeNotificationPending=true;delete bike.chequeNotificationError;clearTimeout(syncTimers.stockBikes);localStorage.setItem('emg-stock-bikes',JSON.stringify(stockBikes));rememberRemoteSnapshot('stockBikes',stockBikes);showToast(`Cheque ${bike.chequeNumber} alterado para A vencer. O aviso será enviado à Contabilidade no próximo minuto.`);return true}catch(error){bike.chequeCollectedEarly=false;bike.chequeNotificationPending=true;bike.chequeNotificationError=error.message;clearTimeout(syncTimers.stockBikes);localStorage.setItem('emg-stock-bikes',JSON.stringify(stockBikes));showToast(`Cheque alterado para A vencer, mas o aviso não ficou agendado: ${error.message}`);return false}
};

function openTrackingCodeModal(process,index=8){
 document.querySelector('#trackingCodeModal')?.remove();const modal=document.createElement('div');modal.id='trackingCodeModal';modal.className='modal-backdrop';modal.innerHTML=`<section class="modal small-modal"><header><div><span class="eyebrow">DOCUMENTAÇÃO ENVIADA</span><h2>Registar tracking code</h2></div><button class="icon-btn" data-close-tracking>×</button></header><form><div class="form-section"><label><span>Tracking code</span><input name="trackingCode" required value="${htmlEscape(process.trackingCode||'')}" placeholder="Código de seguimento"></label><p class="cell-sub">O código ficará associado permanentemente a este processo.</p></div><footer><button type="button" class="btn ghost" data-close-tracking>Cancelar</button><button class="btn primary" type="submit">Guardar e validar</button></footer></form></section>`;document.body.append(modal);const close=()=>modal.remove();modal.querySelectorAll('[data-close-tracking]').forEach(button=>button.onclick=close);modal.onclick=event=>{if(event.target===modal)close()};modal.querySelector('form').onsubmit=event=>{event.preventDefault();const validator=sessionEmployeeName()||currentUser?.name||currentUser?.username||'Utilizador';normalizedChecklist(process);process.trackingCode=String(new FormData(event.currentTarget).get('trackingCode')).trim();process.trackingRegisteredBy=validator;process.trackingRegisteredAt=new Date().toISOString();process.checklist[index]=true;process.checkOwners[index]=validator;process.checks=process.checklist.filter(Boolean).length;process.status=checklistStatus(process);process.tone=statusTone(process.status);process.updatedBy=validator;process.updatedAt=new Date().toISOString();save();close();showToast(`Documentação enviada · ${process.trackingCode}`);detail(process.id,'checklist')}}

const detailTrackingBase=detail;
detail=function(id,activeTab='checklist'){detailTrackingBase(id,activeTab);const process=processes.find(value=>value.id===id);if(!process)return;if(activeTab==='checklist'){const button=document.querySelector('[data-check="8"]');if(button&&!process.checklist[8])button.onclick=()=>openTrackingCodeModal(process);const item=button?.closest('.check-item');if(item&&process.trackingCode&&!item.querySelector('.tracking-code'))item.insertAdjacentHTML('beforeend',`<span class="tracking-code">Tracking: <b>${htmlEscape(process.trackingCode)}</b></span>`)}if(process.trackingCode){const aside=view.querySelector('.detail-grid aside .card');if(aside&&!aside.querySelector('[data-process-tracking]'))aside.insertAdjacentHTML('beforeend',`<div class="side-section" data-process-tracking><h3>Envio da documentação</h3><div class="info-row"><span>Tracking code</span><b>${htmlEscape(process.trackingCode)}</b></div></div>`)}};

