openProcessEditor=function(process){openProcessEditorTrackingBase(process);const form=document.querySelector('#processEditForm');if(!form)return;const checklist=form.querySelector('.process-edit-checklist'),field=document.createElement('label');field.className='full process-tracking-field';field.innerHTML=`<span>Tracking code da documentação</span><input name="trackingCode" value="${htmlEscape(process.trackingCode||'')}" placeholder="Obrigatório quando Documentação enviada está validada">`;checklist?.append(field);const sync=()=>{const checked=form.querySelector('[name="processChecklist"][value="8"]')?.checked;field.hidden=!checked;field.querySelector('input').required=!!checked};form.querySelector('[name="processChecklist"][value="8"]')?.addEventListener('change',sync);sync();form.addEventListener('submit',()=>{const code=String(form.elements.trackingCode?.value||'').trim();if(code){process.trackingCode=code;process.trackingRegisteredBy=process.trackingRegisteredBy||sessionEmployeeName();process.trackingRegisteredAt=process.trackingRegisteredAt||new Date().toISOString()}else if(!form.querySelector('[name="processChecklist"][value="8"]')?.checked){delete process.trackingCode;delete process.trackingRegisteredBy;delete process.trackingRegisteredAt}},true)};

function officeBlockPeriod(block){return block?.period||'all'}
function bookingOverlapsOfficeBlock(date,time='09:00',duration=60){const [hour,minute]=String(time).split(':').map(Number),start=hour*60+minute,end=start+Number(duration||60);return officeBlocks.some(block=>{if(block.date!==date)return false;const period=officeBlockPeriod(block);return period==='all'||(period==='morning'&&start<14*60&&end>9*60)||(period==='afternoon'&&start<20*60&&end>14*60)})}
function blockPeriodLabel(period){return period==='morning'?'Manhã':period==='afternoon'?'Tarde':'Dia inteiro'}
