calendarDay=function(date){const dateIso=isoDate(date),events=bookings.filter(booking=>booking.date===dateIso),block=officeBlocks.find(item=>item.date===dateIso),period=officeBlockPeriod(block);return `<div class="calendar-day ${block?'office-day-blocked':''}" data-calendar-slot="${dateIso}">${Array.from({length:11},()=>'<i class="hour-line"></i>').join('')}${block?`<button class="office-block-overlay block-${period}" data-office-block-date="${dateIso}"><b>${blockPeriodLabel(period).toUpperCase()} BLOQUEADA</b><span>${htmlEscape(block.reason)}</span></button>`:''}${events.filter(booking=>{const [hour,minute]=booking.time.split(':').map(Number);return hour*60+minute>=9*60&&hour*60+minute<=20*60}).map(booking=>{const [hour,minute]=booking.time.split(':').map(Number),top=((hour-9)*60+minute)/(11*60)*100,height=Math.max(5,booking.duration/(11*60)*100);return `<button class="calendar-event ${booking.completed||booking.invoice?'event-completed':''}" data-booking-id="${booking.id}" style="top:${top}%;height:${height}%" title="${htmlEscape(booking.client)} — ${htmlEscape(booking.service)}"><b>${booking.time} · ${htmlEscape(booking.service)}</b><small>${htmlEscape(booking.client)}</small><small>${booking.completed?`Pronto · ${euros(booking.amountDue||0)}`:htmlEscape(booking.invoice||booking.bike)}</small></button>`}).join('')}</div>`};
monthCalendarView=function(reference,label){const first=new Date(reference.getFullYear(),reference.getMonth(),1),start=mondayOf(first),days=Array.from({length:42},(_,index)=>{const date=new Date(start);date.setDate(date.getDate()+index);return date});return `<article class="card calendar-card">${calendarToolbar(reference,'month',label)}<div class="month-weekdays">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(day=>`<span>${day}</span>`).join('')}</div><div class="office-month-grid">${days.map(date=>{const dateIso=isoDate(date),events=bookings.filter(booking=>booking.date===dateIso).sort((a,b)=>a.time.localeCompare(b.time)),block=officeBlocks.find(item=>item.date===dateIso);return `<div class="office-month-day ${date.getMonth()!==reference.getMonth()?'outside':''} ${dateIso===isoDate(new Date())?'today':''} ${block?'office-day-blocked':''}" data-month-date="${dateIso}"><button class="month-day-number" data-month-date="${dateIso}">${date.getDate()}</button>${block?`<button class="month-office-block" data-office-block-date="${dateIso}">${blockPeriodLabel(officeBlockPeriod(block))} · ${htmlEscape(block.reason)}</button>`:''}${events.slice(0,3).map(event=>`<button class="month-booking" data-booking-id="${event.id}"><b>${event.time}</b> ${htmlEscape(event.client)}</button>`).join('')}${events.length>3?`<small>+${events.length-3} marcações</small>`:''}</div>`}).join('')}</div></article>`};
