const excludedAccountingInvoices=new Set(['FT2026A1/7092','FT2026A1/6302'].map(value=>value.replace(/\s/g,'').toUpperCase()));
accountingCheques=function(){return stockBikes.filter(item=>item.chequeNumber&&!excludedAccountingInvoices.has(String(item.invoiceNumber||'').replace(/\s/g,'').toUpperCase())).map(item=>{const dueDate=item.chequeDueDate||chequeDueDate(item.chequeCreatedAt,item.chequeTerm),documentNumber=item.invoiceNumber||item.reference||'Sem número';return{...item,dueDate,documentNumber}}).sort((a,b)=>String(a.dueDate||'9999-12-31').localeCompare(String(b.dueDate||'9999-12-31')))};

