let accountingFilter='all';
function accountingChequeState(item){const today=isoDate(new Date()),due=String(item.dueDate||'');if(due&&due<today)return'overdue';if(item.chequeCollectedEarly||item.chequeCollectionTriggeredAt)return'due';return'pending'}
function chequeDaysRemaining(item){if(!item.dueDate)return null;const today=new Date(`${isoDate(new Date())}T12:00:00`),due=new Date(`${item.dueDate}T12:00:00`),calendarDays=Math.round((due-today)/86400000);if(calendarDays<=0||(!item.chequeCollectedEarly&&!item.chequeCollectionTriggeredAt))return calendarDays;let businessDays=0,cursor=new Date(today);while(cursor<due){cursor.setDate(cursor.getDate()+1);if(cursor.getDay()!==0&&cursor.getDay()!==6)businessDays++}return businessDays}
