function blockTimeBounds(block){const legacy=officeBlockPeriod(block);if(legacy==='morning')return[8*60,14*60];if(legacy==='afternoon')return[14*60,20*60];if(legacy==='all'||block.mode==='all')return[8*60,20*60];const [startHour,startMinute]=String(block.startTime||'08:00').split(':').map(Number),[endHour,endMinute]=String(block.endTime||'09:00').split(':').map(Number);return[startHour*60+startMinute,endHour*60+endMinute]}
function layoutOfficeBookings(events){const sorted=[...events].sort((a,b)=>String(a.time).localeCompare(String(b.time))),clusters=[],layout=new Map();let cluster=[],clusterEnd=-1;const flush=()=>{if(!cluster.length)return;const lanes=[];cluster.forEach(booking=>{const [hour,minute]=String(booking.time).split(':').map(Number),start=hour*60+minute,end=start+Number(booking.duration||60);let lane=lanes.findIndex(value=>value<=start);if(lane<0){lane=lanes.length;lanes.push(end)}else lanes[lane]=end;layout.set(String(booking.id),{lane,columns:0})});const columns=Math.max(1,lanes.length);cluster.forEach(booking=>layout.get(String(booking.id)).columns=columns);cluster=[];clusterEnd=-1};sorted.forEach(booking=>{const [hour,minute]=String(booking.time).split(':').map(Number),start=hour*60+minute,end=start+Number(booking.duration||60);if(cluster.length&&start>=clusterEnd)flush();cluster.push(booking);clusterEnd=Math.max(clusterEnd,end)});flush();return layout}
