function exportOrdersPdf(){const rows=orders.map(order=>({order,values:orderFinancials(order)})),totals=rows.reduce((sum,row)=>{sum.revenue+=row.values.revenue;if(row.values.hasCost){sum.cost+=row.values.cost;sum.fee+=row.values.fee;sum.profit+=row.values.profit;sum.costedRevenue+=row.values.revenue}return sum},{revenue:0,cost:0,fee:0,profit:0,costedRevenue:0}),margin=totals.costedRevenue?totals.profit/totals.costedRevenue*100:0,popup=window.open('','_blank');if(!popup){showToast('O navegador bloqueou a janela de exportação');return}popup.document.write(`<!doctype html><html lang="pt"><head><meta charset="utf-8"><title>Encomendas Motogreen</title><style>@page{size:A4 landscape;margin:10mm}body{font-family:Arial,sans-serif;color:#173027}header{border-bottom:3px solid #15935f;padding-bottom:10px;margin-bottom:14px}h1{margin:0;font-size:22px}p{margin:5px 0;color:#66756e}table{width:100%;border-collapse:collapse;font-size:9px}th{background:#0d563e;color:#fff;text-align:left}th,td{padding:6px;border:1px solid #d8e5df;vertical-align:top}small{display:block;color:#66756e;margin-top:3px}tfoot th{background:#e8f5ef;color:#173027;font-size:10px}.positive{color:#08764d}.negative{color:#b12d2d}@media print{thead{display:table-header-group}tfoot{display:table-row-group}}</style></head><body><header><h1>E-Motogreen · Encomendas</h1><p>Lista financeira exportada em ${htmlEscape(new Date().toLocaleString('pt-PT'))} · ${orders.length} encomendas</p></header><table><thead><tr><th>Encomenda / data</th><th>Cliente</th><th>Produto / referência</th><th>Fornecedor</th><th>Pagamento</th><th>Faturado</th><th>Custo</th><th>Comissão</th><th>Lucro / margem</th><th>Estado / notas</th></tr></thead><tbody>${rows.length?rows.map(({order,values})=>`<tr><td><b>${htmlEscape(order.number||'Sem número')}</b><small>${order.orderDate?new Date(`${order.orderDate}T12:00:00`).toLocaleDateString('pt-PT'):'Sem data'}</small></td><td>${htmlEscape(order.clientName||'')}</td><td><b>${htmlEscape(order.product||'')}</b><small>${htmlEscape(order.reference||'Sem referência')}</small></td><td>${htmlEscape(order.supplier||'')}</td><td>${htmlEscape(order.paymentMethod||'Transferência bancária')}</td><td><b>${euros(values.revenue)}</b><small>Produto: ${euros(values.saleProduct)}<br>Portes: ${euros(values.saleShipping)}</small></td><td>${values.hasCost?`<b>${euros(values.cost)}</b><small>Produto: ${euros(values.purchaseProduct)}<br>Portes: ${euros(values.purchaseShipping)}</small>`:'Por apurar'}</td><td>${values.hasCost?euros(values.fee):'—'}</td><td>${values.hasCost?`<b class="${values.profit>=0?'positive':'negative'}">${euros(values.profit)}</b><small>${values.margin.toFixed(2).replace('.',',')}%</small>`:'Por apurar'}</td><td><b>${htmlEscape(order.status||'')}</b><small>${htmlEscape(order.notes||'Sem notas')}</small></td></tr>`).join(''):'<tr><td colspan="10">Sem encomendas registadas.</td></tr>'}</tbody><tfoot><tr><th colspan="5">TOTAL APURADO</th><th>${euros(totals.revenue)}</th><th>${euros(totals.cost)}</th><th>${euros(totals.fee)}</th><th>${euros(totals.profit)}<small>${margin.toFixed(2).replace('.',',')}%</small></th><th></th></tr></tfoot></table><script>window.onload=()=>window.print()<\/script></body></html>`);popup.document.close()}
ordersPage=function(){ordersPageImmediatePersistenceBase();const title=document.querySelector('.page-head h1');if(title)title.textContent='Encomendas';document.querySelectorAll('.card-head h3').forEach(heading=>{if(heading.textContent.trim()==='Encomendas Pendentes')heading.textContent='Encomendas'});const actions=document.querySelector('.page-head .head-actions');if(actions&&!actions.querySelector('#exportOrdersPdf'))actions.innerHTML='<button class="btn primary" id="exportOrdersPdf">⇩ Exportar PDF</button>';document.querySelector('#exportOrdersPdf')?.addEventListener('click',exportOrdersPdf);const form=document.querySelector('#orderForm');if(!form)return;form.onsubmit=async event=>{event.preventDefault();const submit=form.querySelector('[type="submit"]'),number=String(new FormData(form).get('number')).trim();if(number&&orders.some(order=>String(order.number||'').toLowerCase()===number.toLowerCase())){showToast('Já existe uma encomenda com este número');return}const record=readOrderFields(form,{id:newEntityId(),uid:`order-${newEntityId()}`});orders.unshift(record);clearTimeout(syncTimers.orders);localStorage.setItem('emg-orders',JSON.stringify(orders));submit.disabled=true;try{if(remoteMode){const delta=changedRecords('orders',orders);const response=await apiRequest('state-write.php',{method:'POST',body:encodedStateBody({resource:'orders',data:delta,partial:true})});if(Array.isArray(response.data))applyServerResource('orders',response.data)}else rememberRemoteSnapshot('orders',orders);showToast('Encomenda adicionada e gravada no servidor');ordersPage()}catch(error){orders=orders.filter(item=>item!==record);localStorage.setItem('emg-orders',JSON.stringify(orders));submit.disabled=false;showToast(`Não foi possível gravar a encomenda: ${error.message}`)}}};
exportAgendaDay=function(date){const dayBookings=bookings.filter(booking=>booking.date===date).sort((a,b)=>String(a.time||'').localeCompare(String(b.time||''))),dayNotes=officeNotes.filter(note=>note.date===date),label=new Intl.DateTimeFormat('pt-PT',{weekday:'long',day:'2-digit',month:'long',year:'numeric'}).format(new Date(`${date}T12:00:00`)),popup=window.open('','_blank');if(!popup){showToast('O navegador bloqueou a janela de exportação');return}const bookingMarkup=dayBookings.length?dayBookings.map(booking=>`<div class="item"><span class="time">${htmlEscape(booking.time||'')}</span><div><b>${htmlEscape(booking.service||'')}</b><small>${htmlEscape(booking.client||'')} · ${htmlEscape(booking.phone||'')}</small><small>${htmlEscape(booking.bike||'')}</small></div><div><b>${htmlEscape(booking.technician||'')}</b><small>${Number(booking.duration||0)} minutos</small></div></div>`).join(''):'<div class="empty">Sem marcações para este dia.</div>';const noteMarkup=dayNotes.length?dayNotes.map(note=>`<div class="note"><b>Nota para o mecânico</b><div>${htmlEscape(note.text||'')}</div><small>Registado por ${htmlEscape(note.createdBy||'Utilizador')}</small></div>`).join(''):'<div class="empty compact">Sem notas para este dia.</div>';popup.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Agenda Oficina — ${date}</title><style>body{font-family:Arial,sans-serif;color:#173027;padding:35px}header{border-bottom:3px solid #15935f;padding-bottom:16px;margin-bottom:22px}h1{margin:0;font-size:24px}h2{font-size:18px;margin:28px 0 8px;color:#0d563e}p{color:#66756e}.item{display:grid;grid-template-columns:80px 1fr 160px;gap:15px;padding:15px 0;border-bottom:1px solid #ddd}.time{font-size:18px;font-weight:bold;color:#14764f}.item b,.item span,.item small{display:block}.item small,.note small{color:#68756e;margin-top:4px}.note{padding:14px 16px;margin:8px 0;background:#fff7d6;border-left:4px solid #d7a700;white-space:pre-wrap}.note b{display:block;margin-bottom:7px}.empty{padding:30px;text-align:center;color:#777}.empty.compact{padding:16px}@media print{body{padding:10px}}</style></head><body><header><h1>E-Motogreen · Agenda da Oficina</h1><p>${htmlEscape(label)}</p></header><h2>Marcações</h2>${bookingMarkup}<h2>Notas da Oficina</h2>${noteMarkup}<script>window.onload=()=>window.print()<\/script></body></html>`);popup.document.close()};
const reliableClientSubmitBase=document.querySelector('#clientForm').onsubmit;
document.querySelector('#clientForm').onsubmit=async function(event){const known=new Set(clients.map(recordKey));reliableClientSubmitBase.call(this,event);const created=clients.find(item=>!known.has(recordKey(item)));if(!created)return;try{await persistResourceNow('clients',clients);showToast('Cliente gravado e confirmado no servidor')}catch(error){stageServerSync('clients',[created]);showToast('O cliente ficou em fila de segurança. A plataforma voltará a tentar gravá-lo automaticamente.')}};
const reliableProcessSubmitBase=document.querySelector('#processForm').onsubmit;
document.querySelector('#processForm').onsubmit=async function(event){const knownProcesses=new Set(processes.map(recordKey)),knownClients=new Set(clients.map(recordKey));reliableProcessSubmitBase.call(this,event);await Promise.resolve();const createdProcess=processes.find(item=>!knownProcesses.has(recordKey(item))),createdClient=clients.find(item=>!knownClients.has(recordKey(item)));if(!createdProcess)return;try{if(createdClient)await persistResourceNow('clients',clients);if(changedRecords('stockBikes',stockBikes).length)await persistResourceNow('stockBikes',stockBikes);await persistResourceNow('processes',processes);showToast('Processo gravado e confirmado no servidor')}catch(error){stageServerSync('processes',[createdProcess]);if(createdClient)stageServerSync('clients',[createdClient]);showToast('O processo ficou em fila de segurança. A plataforma voltará a tentar gravá-lo automaticamente.')}};
